import re


def parse(line):
    found = re.search(r"(?P<stamp>\d{4}-\d{2}-\d{2}) (?P<level>[A-Z]+) (?P<zone>\w+)", line)
    if found is None:
        return None
    return found.groupdict()


def redact(line):
    return re.sub(r"\d{4}-\d{2}-\d{2}", "<date>", line)


print(redact("2041-03-02 ERR north"))
